    mul.lo.s64 %rd46, %rd46, %rd56;
    add.s64 %rd45, %rd45, %rd46;
    cvt.s64.s32 %rd47, %r54;
    mul.lo.s64 %rd47, %rd47, %rd57;
    add.s64 %rd45, %rd45, %rd47;
