// Structural rewrite: CTA-level output/spatial tiling.
// Each CTA covers a contiguous block of output W-tiles; each thread owns a
// 1x1x4 tile of adjacent outputs along W (unit stride/dilation fast case),
// keeping 4 accumulators in registers so every loaded weight tap is reused
// across 4 outputs and input/weight addresses are advanced incrementally
// instead of recomputed with per-tap cvt/mul chains.
.visible .entry conv_transpose3d_kernel_tiled(
    .param .u64 input_ptr,
    .param .u64 weight_ptr,
    .param .u64 bias_ptr,
    .param .u64 output_ptr,
    .param .s32 in_channels,
    .param .s32 out_channels,
    .param .s32 in_d,
    .param .s32 in_h,
    .param .s32 in_w,
    .param .s32 out_d,
    .param .s32 out_h,
    .param .s32 out_w,
    .param .s32 kernel_d,
    .param .s32 kernel_h,
    .param .s32 kernel_w,
    .param .s32 stride_d,
    .param .s32 stride_h,
    .param .s32 stride_w,
    .param .s32 pad_d,
    .param .s32 pad_h,
    .param .s32 pad_w,
    .param .s32 dilation_d,
    .param .s32 dilation_h,
    .param .s32 dilation_w,
    .param .s32 groups,
    .param .s64 input_stride_n,
    .param .s64 input_stride_c,
    .param .s64 input_stride_d,
    .param .s64 input_stride_h,
    .param .s64 input_stride_w,
    .param .s64 weight_stride_ic,
    .param .s64 weight_stride_oc,
    .param .s64 weight_stride_kd,
    .param .s64 weight_stride_kh,
    .param .s64 weight_stride_kw,
    .param .s64 bias_stride,
    .param .s32 has_bias,
    .param .u64 total_elements
)
{
    .reg .pred %p<32>;
    .reg .b32 %r<128>;
    .reg .b64 %rd<128>;
    .reg .f32 %f<32>;
    ld.param.u64 %rd0, [input_ptr];
    ld.param.u64 %rd1, [weight_ptr];
    ld.param.u64 %rd2, [bias_ptr];
    ld.param.u64 %rd3, [output_ptr];
    ld.param.u64 %rd4, [total_elements];
    ld.param.s32 %r20, [in_channels];
    ld.param.s32 %r21, [out_channels];
    ld.param.s32 %r22, [in_d];
    ld.param.s32 %r23, [in_h];
    ld.param.s32 %r24, [in_w];
    ld.param.s32 %r25, [out_d];
    ld.param.s32 %r26, [out_h];
    ld.param.s32 %r27, [out_w];
    ld.param.s32 %r28, [kernel_d];
    ld.param.s32 %r29, [kernel_h];
    ld.param.s32 %r30, [kernel_w];
    ld.param.s32 %r34, [pad_d];
    ld.param.s32 %r35, [pad_h];
    ld.param.s32 %r36, [pad_w];
    ld.param.s32 %r40, [groups];
    ld.param.s32 %r41, [has_bias];
    ld.param.s64 %rd50, [input_stride_n];
    ld.param.s64 %rd51, [input_stride_c];
    ld.param.s64 %rd52, [input_stride_d];
    ld.param.s64 %rd53, [input_stride_h];
    ld.param.s64 %rd54, [input_stride_w];
    ld.param.s64 %rd55, [weight_stride_ic];
    ld.param.s64 %rd56, [weight_stride_oc];
    ld.param.s64 %rd57, [weight_stride_kd];
    ld.param.s64 %rd58, [weight_stride_kh];
    ld.param.s64 %rd59, [weight_stride_kw];
    ld.param.s64 %rd60, [bias_stride];
    mov.u32 %r0, %ctaid.x;
    mov.u32 %r1, %ntid.x;
    mov.u32 %r2, %tid.x;
    cvt.u64.u32 %rd10, %r0;
    cvt.u64.u32 %rd11, %r1;
    mul.lo.u64 %rd10, %rd10, %rd11;
    cvt.u64.u32 %rd12, %r2;
    add.u64 %rd10, %rd10, %rd12;
    setp.ge.u64 %p0, %rd10, %rd4;
    @%p0 bra TDONE;
    add.s32 %r60, %r27, 3;
    shr.s32 %r60, %r60, 2;
    cvt.u64.u32 %rd20, %r60;
    rem.u64 %rd21, %rd10, %rd20;
    div.u64 %rd22, %rd10, %rd20;
    shl.b64 %rd21, %rd21, 2;
    cvt.u32.u64 %r42, %rd21;
    cvt.u64.u32 %rd23, %r26;
    rem.u64 %rd24, %rd22, %rd23;
    div.u64 %rd25, %rd22, %rd23;
    cvt.u32.u64 %r43, %rd24;
    cvt.u64.u32 %rd26, %r25;
    rem.u64 %rd27, %rd25, %rd26;
    div.u64 %rd28, %rd25, %rd26;
    cvt.u32.u64 %r44, %rd27;
    cvt.u64.u32 %rd29, %r21;
    rem.u64 %rd30, %rd28, %rd29;
    div.u64 %rd31, %rd28, %rd29;
    cvt.u32.u64 %r45, %rd30;
    cvt.u32.u64 %r46, %rd31;
    div.s32 %r47, %r21, %r40;
    div.s32 %r48, %r45, %r47;
    rem.s32 %r49, %r45, %r47;
    div.s32 %r50, %r20, %r40;
    mul.lo.s32 %r51, %r48, %r50;
    add.s32 %r52, %r51, %r50;
    mov.f32 %f10, 0f00000000;
    mov.f32 %f11, 0f00000000;
    mov.f32 %f12, 0f00000000;
    mov.f32 %f13, 0f00000000;
    shl.b64 %rd61, %rd54, 2;
    shl.b64 %rd68, %rd59, 2;
    // Loop-invariant code motion for the kernel_w==3 register-blocked path:
    // the sliding input window origin column, the whole-window in-bounds
    // test, the window base byte-offset, and the kernel_w==3 selector all
    // depend only on the thread's output tile origin -- not on (ic,kd,kh) --
    // so compute them once here instead of on every inner-loop iteration,
    // cutting issue pressure in the compute-bound hot loop.
    setp.eq.s32 %p21, %r30, 3;
    add.s32 %r85, %r42, %r36;
    add.s32 %r85, %r85, -2;
    setp.ge.s32 %p22, %r85, 0;
    add.s32 %r86, %r85, 5;
    setp.lt.s32 %p23, %r86, %r24;
    and.pred %p22, %p22, %p23;
    cvt.s64.s32 %rd69, %r85;
    mul.lo.s64 %rd69, %rd69, %rd61;
    mov.s32 %r53, %r51;
TIC_LOOP:
    setp.ge.s32 %p0, %r53, %r52;
    @%p0 bra TFINISH;
    cvt.s64.s32 %rd40, %r46;
    mul.lo.s64 %rd40, %rd40, %rd50;
    cvt.s64.s32 %rd41, %r53;
    mul.lo.s64 %rd41, %rd41, %rd51;
    add.s64 %rd40, %rd40, %rd41;
    shl.b64 %rd40, %rd40, 2;
    add.s64 %rd62, %rd0, %rd40;
    cvt.s64.s32 %rd42, %r53;
    mul.lo.s64 %rd42, %rd42, %rd55;
    cvt.s64.s32 %rd43, %r49;
    mul.lo.s64 %rd43, %rd43, %rd56;
